import{_ as e,a as i,c as a,ac as r}from"./chunks/framework.BSuaGltH.js";const y=JSON.parse('{"title":"怎样理解古代筮法：蓍草、钱币、动爻与解释边界","description":"核读《系辞》大衍章、朱熹《筮仪》及《易学启蒙》传本，给出可验算的揲蓍步骤、钱币概率和多动爻规则的来源边界。","frontmatter":{"title":"怎样理解古代筮法：蓍草、钱币、动爻与解释边界","description":"核读《系辞》大衍章、朱熹《筮仪》及《易学启蒙》传本，给出可验算的揲蓍步骤、钱币概率和多动爻规则的来源边界。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"易经专题","summary":"核读《系辞》大衍章、朱熹《筮仪》及《易学启蒙》传本，给出可验算的揲蓍步骤、钱币概率和多动爻规则的来源边界。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"易经：先后天、河洛与历史图谱","link":"/life/personal/yijing/diagrams"},"next":{"text":"易经：后世易学与术数分界","link":"/life/personal/yijing/traditions"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"易经：先后天、河洛与历史图谱","link":"/life/personal/yijing/diagrams"},"next":{"text":"易经：后世易学与术数分界","link":"/life/personal/yijing/traditions"}},"headers":[],"relativePath":"life/personal/yijing/divination.md","filePath":"life/personal/yijing/divination.md"}'),l={name:"life/personal/yijing/divination.md"};function d(n,t,h,g,s,o){return i(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="怎样理解古代筮法-蓍草、钱币、动爻与解释边界" tabindex="-1">怎样理解古代筮法：蓍草、钱币、动爻与解释边界 <a class="header-anchor" href="#怎样理解古代筮法-蓍草、钱币、动爻与解释边界" aria-label="Permalink to &quot;怎样理解古代筮法：蓍草、钱币、动爻与解释边界&quot;">​</a></h1><p>学习筮法，可以把它当作理解古代知识活动的一部分：人们怎样设置问题、生成卦象、选取文本，并用仪式表达郑重。算法可以重复和核算，文本可以校读；这些并不等于它对现实未来具有已经证实的预测能力。学习者应把“算得是否符合约定”与“解释是否有证据”分开。</p><p>本篇不把今人的三枚钱币法说成《周易》古经原有步骤，也不把朱熹整理的全部取辞规则说成周代统一制度。不同层次的来源，见<a href="/life/personal/yijing/text-history">文本史</a>与<a href="/life/personal/yijing/commentaries">注家比较</a>。</p><h2 id="卜与筮首先不是同一操作" tabindex="-1">卜与筮首先不是同一操作 <a class="header-anchor" href="#卜与筮首先不是同一操作" aria-label="Permalink to &quot;卜与筮首先不是同一操作&quot;">​</a></h2><p>古代文献中，卜常与龟甲兽骨等灼兆活动有关，筮常与蓍策操作有关；具体时代与语境仍须分别判断。今天把一切都叫“占卜”方便交流，但读古籍时不能因此忽略材料、操作和判断方式的差别。</p><p>本篇只解释与《周易》阅读相关的蓍筮和后起钱币简法，不扩展为纳甲、六亲、六神、干支历法等整套后世术数。这些系统各有自己的形成历史和规则，不能只因也使用六爻，就说全部内容都直接出自卦爻辞。</p><h2 id="《系辞》大衍章实际说了什么" tabindex="-1">《系辞》大衍章实际说了什么 <a class="header-anchor" href="#《系辞》大衍章实际说了什么" aria-label="Permalink to &quot;《系辞》大衍章实际说了什么&quot;">​</a></h2><p>《系辞上》有如下程序纲要：</p><blockquote><p>大衍之数五十，其用四十有九。分而为二以象两，挂一以象三，揲之以四以象四时，归奇于扐以象闰。</p></blockquote><p>随后又说“四营而成易，十有八变而成卦”。原文把分、挂、揲、归奇与天地、三才、四时、置闰等象征联系起来；它是一段兼有操作与宇宙秩序说明的文字。<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%82%B3/%E7%B9%AB%E8%BE%AD%E4%B8%8A" target="_blank" rel="noopener noreferrer">《系辞上》大衍章</a>。</p><p>但纲要不是一份把每个细节全部说尽的现代操作手册。“再扐而后挂”等语句怎样落实，各家有讨论；如何安置蓍策、每一变怎样操作、多少次成为一爻、怎样选辞，都还需要注解和后续文献。朱熹《筮仪》给出相当细致的流程，本文据其“三变成爻、十八变成卦”的体系作计算说明。<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%9C%AC%E7%BE%A9_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD" target="_blank" rel="noopener noreferrer">《周易本义》全览所收《筮仪》</a>。</p><p>《筮仪》还写到蓍室、蓍椟、木格、洁衣、焚香与命辞。这些是其礼仪安排的一部分。下面为理解数的生成而抽出算法，是现代教学简化，不声称保留了全部古礼。</p><h2 id="六、七、八、九表示什么" tabindex="-1">六、七、八、九表示什么 <a class="header-anchor" href="#六、七、八、九表示什么" aria-label="Permalink to &quot;六、七、八、九表示什么&quot;">​</a></h2><p>在本篇采用的约定中，每爻最后得到四个数之一：</p><table tabindex="0"><thead><tr><th style="text-align:right;">得数</th><th>名称</th><th>本卦画法</th><th>形成之卦时</th></tr></thead><tbody><tr><td style="text-align:right;">6</td><td>老阴</td><td>阴爻</td><td>变为阳爻</td></tr><tr><td style="text-align:right;">7</td><td>少阳</td><td>阳爻</td><td>不变</td></tr><tr><td style="text-align:right;">8</td><td>少阴</td><td>阴爻</td><td>不变</td></tr><tr><td style="text-align:right;">9</td><td>老阳</td><td>阳爻</td><td>变为阴爻</td></tr></tbody></table><p>六爻一定从下往上记录：第一次所得是初爻，第六次所得是上爻。先保存六个数，再画卦，比只记阴阳更不容易丢失动爻信息。</p><p>“经文阳爻题作九、阴爻题作六”与“这一回起得老阳九、老阴六”也不能混淆。经文的“九二”是阳爻所在位置的名称，并不证明每次遇到该卦的第二爻都一定变化。少阳七也画阳爻，只是在这套起卦规则里不变。</p><h2 id="揲蓍的一个可核算版本" tabindex="-1">揲蓍的一个可核算版本 <a class="header-anchor" href="#揲蓍的一个可核算版本" aria-label="Permalink to &quot;揲蓍的一个可核算版本&quot;">​</a></h2><p>准备五十根等长签筹。先取一根放在旁边，本次成卦不再参与；余四十九根用于每一爻。古代用蓍，教学用签筹只是为理解操作。</p><p>每一爻连续做三变。每一变依次进行：</p><ol><li>将当前签筹分成左右两堆。为避免空堆，本教学算法规定左堆至少一根，右堆至少两根。</li><li>从右堆取出一根，叫“挂一”。</li><li>左堆按四根一组数，留下最后一至四根；能被四整除时，留下四根，不记作零。</li><li>右堆扣除挂一之后，也按同样规则数出最后一至四根。</li><li>把挂一及左右余数放到一旁。本变结束，将两堆数过的签筹合并，作为下一变的当前签筹。</li></ol><p>“一变”包含上述一整轮，不是一根签筹变化。做完三变，将仍参与的签筹数除以四，得到本爻的六、七、八或九。记录后，把本爻三次取出的签筹全部收回，再用四十九根起下一爻。旁边最初取出的一根始终不参与。</p><p>这里规定左右非空，是为了让“末组留四”的算术规则没有空堆歧义；它是教学说明的明确约束，并非宣称古籍已经给出同样的随机抽样模型。</p><h3 id="用一个完整数字例子检查操作" tabindex="-1">用一个完整数字例子检查操作 <a class="header-anchor" href="#用一个完整数字例子检查操作" aria-label="Permalink to &quot;用一个完整数字例子检查操作&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变次</th><th style="text-align:right;">开始总数</th><th style="text-align:right;">左堆</th><th style="text-align:right;">原右堆</th><th style="text-align:right;">挂一后右堆</th><th style="text-align:right;">左余</th><th style="text-align:right;">右余</th><th style="text-align:right;">本变取出</th><th style="text-align:right;">剩余</th></tr></thead><tbody><tr><td>第一变</td><td style="text-align:right;">49</td><td style="text-align:right;">20</td><td style="text-align:right;">29</td><td style="text-align:right;">28</td><td style="text-align:right;">4</td><td style="text-align:right;">4</td><td style="text-align:right;">1＋4＋4＝9</td><td style="text-align:right;">40</td></tr><tr><td>第二变</td><td style="text-align:right;">40</td><td style="text-align:right;">18</td><td style="text-align:right;">22</td><td style="text-align:right;">21</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td><td style="text-align:right;">1＋2＋1＝4</td><td style="text-align:right;">36</td></tr><tr><td>第三变</td><td style="text-align:right;">36</td><td style="text-align:right;">17</td><td style="text-align:right;">19</td><td style="text-align:right;">18</td><td style="text-align:right;">1</td><td style="text-align:right;">2</td><td style="text-align:right;">1＋1＋2＝4</td><td style="text-align:right;">32</td></tr></tbody></table><p>最终三十二除以四等于八，是少阴，画阴爻而不变。这是说明算法的指定数字例子，没有关于现实事件的占验含义。</p><p>第一变取出的总数只可能是五或九；第二、三变只可能是四或八。三变结束，剩余只可能是二十四、二十八、三十二、三十六，对应六、七、八、九。若得到二十六或三十四，说明操作或记录出了错，不能通过临时改变解释把错误“讲通”。</p><h3 id="为什么整除时要留四" tabindex="-1">为什么整除时要留四 <a class="header-anchor" href="#为什么整除时要留四" aria-label="Permalink to &quot;为什么整除时要留四&quot;">​</a></h3><p>按这套操作，“余”指末组尚留手中的策，不是计算机通常返回零的除法余数。以二十根为例，取去四组后留四根。如果直接用 <code>20 % 4 = 0</code> 代替，会破坏每一变应有的取出数。</p><p>对正整数 <code>n</code>，可把末组余数写成：<code>r(n) = ((n - 1) mod 4) + 1</code>。这里 <code>mod</code> 表示除法余数。这一写法只是现代算术表达，不是古籍中的公式。验算时先检查左右两堆进入数四步骤时都大于零。</p><h2 id="钱币法-更简便-但概率并不相同" tabindex="-1">钱币法：更简便，但概率并不相同 <a class="header-anchor" href="#钱币法-更简便-但概率并不相同" aria-label="Permalink to &quot;钱币法：更简便，但概率并不相同&quot;">​</a></h2><p>用三枚硬币，每次同时投掷一次。事先固定一种面记二，另一面记三，把三枚的值相加，得到六至九；重复六次，从初爻往上记录。哪一面记二、哪一面记三，各种实践约定可能不同，必须开始前写清楚，不能看结果后更换。</p><p>在每枚硬币两面等概率、彼此独立的模型下：</p><table tabindex="0"><thead><tr><th style="text-align:right;">得数</th><th style="text-align:right;">组合数量</th><th style="text-align:right;">概率</th></tr></thead><tbody><tr><td style="text-align:right;">6</td><td style="text-align:right;">二、二、二，共一种</td><td style="text-align:right;">1/8</td></tr><tr><td style="text-align:right;">7</td><td style="text-align:right;">两个二、一个三，共三种排列</td><td style="text-align:right;">3/8</td></tr><tr><td style="text-align:right;">8</td><td style="text-align:right;">一个二、两个三，共三种排列</td><td style="text-align:right;">3/8</td></tr><tr><td style="text-align:right;">9</td><td style="text-align:right;">三、三、三，共一种</td><td style="text-align:right;">1/8</td></tr></tbody></table><p>例如事前约定正面记二，出现两正一反就是七，不是因为看起来“阳比较多”而改判为九。数值约定是算法的一部分。</p><p>常见蓍法概率则写成六为1/16、七为5/16、八为7/16、九为3/16。这组数建立在传统理想化余数组合等可能的模型上：第一变去五的概率为3/4、去九为1/4，后两变去四或八各为1/2，并按相应独立条件计算。真实手分签筹的习惯可能影响分布；在程序里对所有切分点简单均匀抽样，也不必然精确得到这组分数。</p><p>两种模型下动爻总概率都是1/4，但老阴、老阳以及少阴、少阳的分布不同。<strong>“都是六七八九”不等于两种方法完全等价。</strong> 概率计算验证的是生成器的分布，不是解释文本预测现实的准确度。</p><h2 id="从本卦到之卦-一个可画出来的例子" tabindex="-1">从本卦到之卦：一个可画出来的例子 <a class="header-anchor" href="#从本卦到之卦-一个可画出来的例子" aria-label="Permalink to &quot;从本卦到之卦：一个可画出来的例子&quot;">​</a></h2><p>假设自下而上得到：七、八、九、八、七、六。本卦阴阳依次为阳、阴、阳、阴、阳、阴，下卦离、上卦坎，是既济。第三爻九与第六爻六是动爻，把它们翻转后，自下而上成为阳、阴、阴、阴、阳、阳，下卦震、上卦巽，是益。</p><p>所以可记“既济之益，九三、上六动”。这里的“之”首先是按规则所得的变化关系，不应未经说明就翻译为“现实一定从既济发展到益”。既济的两条动爻仍分别读九三、上六；查之卦时才按益卦相应爻位查辞，不能把两个卦的辞句混到一张表里。</p><h2 id="多动爻读哪一段-必须先说采用哪套规则" tabindex="-1">多动爻读哪一段：必须先说采用哪套规则 <a class="header-anchor" href="#多动爻读哪一段-必须先说采用哪套规则" aria-label="Permalink to &quot;多动爻读哪一段：必须先说采用哪套规则&quot;">​</a></h2><p>朱熹《易学启蒙》系统形成了一套影响很大的取辞办法。以下依据《易学启蒙通释》所录“考变占”正文与解释整理；这是一种历史上有影响的方案，不能说成《周易》经文唯一明定的规则。<a href="https://www.shidianguji.com/book/SK0061/chapter/1l9qr24ok8562" target="_blank" rel="noopener noreferrer">《易学启蒙通释·考变占》</a>。</p><table tabindex="0"><thead><tr><th style="text-align:right;">动爻数</th><th>该系统的主要取辞办法</th><th>需要保留的说明</th></tr></thead><tbody><tr><td style="text-align:right;">0</td><td>本卦卦辞</td><td>此处“彖辞”指卦辞，不是把《彖传》当作卦辞</td></tr><tr><td style="text-align:right;">1</td><td>本卦该动爻爻辞</td><td>同时保留全卦语境</td></tr><tr><td style="text-align:right;">2</td><td>本卦两动爻爻辞，以上爻为主</td><td>正文明言属于推例</td></tr><tr><td style="text-align:right;">3</td><td>本卦与之卦卦辞，本为贞、之为悔</td><td>配套卦变图另分前十、后十，不能简化为一律本卦主断</td></tr><tr><td style="text-align:right;">4</td><td>之卦两个未变爻的爻辞，以下爻为主</td><td>此项也明言属于推例</td></tr><tr><td style="text-align:right;">5</td><td>之卦唯一未变爻的爻辞</td><td>与某些古代筮例怎样对应，存在解释问题</td></tr><tr><td style="text-align:right;">6</td><td>乾、坤读用九、用六；其他卦读之卦卦辞</td><td>不是任何六爻皆动都读乾坤二用</td></tr></tbody></table><p>“考变占”在二爻变处直接写“经传无文，今以例推之，当如此”，四爻变处也有同样的说明。这是很重要的证据：提出规则的人已经标明哪些属于推论，今天更不应把它说成没有争议的上古统一法。</p><p>三爻变尤其容易被网络简表抹平。原系统将二十种三爻变情况按配套图分成前十与后十，涉及主贞、主悔。若没有核对该图，应明确说“本次并读两卦，未定唯一主辞”，不要把自己的教学简化冒充朱熹原规则。上面的既济之益例子属于二爻动，按该表并读既济九三、上六，以上六为主；这仅说明怎样执行所选规则。</p><h2 id="古人也争论规则-并非只剩一套秘密答案" tabindex="-1">古人也争论规则，并非只剩一套秘密答案 <a class="header-anchor" href="#古人也争论规则-并非只剩一套秘密答案" aria-label="Permalink to &quot;古人也争论规则，并非只剩一套秘密答案&quot;">​</a></h2><p>黄宗羲《易学象数论·占法》列出“启蒙占法”“王氏占法”“丰南禺占法”等不同方案，批评某些取辞安排，并提出自己的理解。这说明多动爻解释本来就是一个讨论领域。看到分歧时，应比较所援引的《左传》《国语》筮例、采用的前提和能否一致解释案例，而非把不同规则任意混用。<a href="https://zh.wikisource.org/wiki/%E6%98%93%E5%AD%B8%E8%B1%A1%E6%95%B8%E8%AB%96/%E5%8D%A0%E6%B3%95" target="_blank" rel="noopener noreferrer">《易学象数论·占法》</a>。</p><p>“古人记载某次占得很准”也不是现代意义上的可靠性检验。传世故事可能经过选择、解释与后见之明的组织；若只有应验故事，没有所有未应验记录和事前判定标准，就不能据此计算预测准确率。</p><h2 id="怎样做一次有学习价值的记录" tabindex="-1">怎样做一次有学习价值的记录 <a class="header-anchor" href="#怎样做一次有学习价值的记录" aria-label="Permalink to &quot;怎样做一次有学习价值的记录&quot;">​</a></h2><p>记录日期、原问题、采用方法、硬币记值或蓍法约定、六个原始数、本卦、动爻、之卦、取辞规则、原文与解释。再另写“这些文本促使我补问的现实问题”，例如资源是否足够、承诺是否明确、有没有可逆的小规模尝试。</p><p>避免不断重起直到出现想要的答案，也避免结果出现后再挑一句貌似贴合的辞。若练习的目标是理解文本，可以不占任何现实问题，直接指定六个数，核算卦变并查读相关经传。涉及医疗、财务或他人重大权益的决定，仍须依据相应事实与专业判断，不能用抽签结果替代。</p><p>本篇已核读大衍章、《筮仪》、乾卦《本义》及“考变占”传本，算术例子和硬币枚举为独立验算。没有声称复原先秦所有筮法，也没有对占验有效性作实验验证。继续可读<a href="/life/personal/yijing/reading-practice">不依赖起卦的经传练习</a>与<a href="/life/personal/yijing/philosophy">时位、变通的思想层次</a>。<a href="/life/personal/yijing/overview">返回易经专题</a>。</p>',52)])])}const x=e(l,[["render",d]]);export{y as __pageData,x as default};
